e_evidence": "Pace beta p=0.0266 but within-ts correlation is 0; no stint clock so poss/48 is period-implied. Mix shifts are clearer than efficiency.", "observed_sample_and_power": "n=28569 periods; mix n_ts=73", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "descriptive"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPS-087"}]}, {"id": "FAM:SF-APPS-059", "label": "Study family SF-APPS-059: Sequence-memory horizon test (per-lag vs aggregated window)", "score": 0.511, "reached_via": ["FAM:SF17 auto_related_family (record_link_related_to) FAM:SF-APPS-059", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.75); FAM:SF-APPS-059 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Sequence-memory horizon test (per-lag vs aggregated window)", "auto_outcome_status": "supported", "observed_hypothesis": "Increasing prior-possession history changes the opponent's next-possession outcome after controlling for game state.", "observed_result": "Per-lag GBT AUC N=0 0.5621 -> N=1 0.5863 (d+0.0242) -> N=3 0.5907 -> N=8 0.5911. R2 0.0051 -> 0.0133. Aggregated window declines after N=1 (AUC 0.5868 -> 0.5687 at N=8). Effective horizon ~2-3 possessions.", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Short-memory horizon is stable OOS; almost all gain is lag-1, plateau by lag 4. Absolute AUC still only ~0.591.", "observed_sample_and_power": "n=1,024,980 possessions; time-split test 2025-26", "observed_verdict": "supported"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-070"}, {"rel": "auto_related_family", "node": "FAM:SF17"}]}], "n_results": 10}

